#include <algorithm>
#include<cstdio>
using namespace std;
void Pascal_Triangle(int size) {

	int a[100][100];
	int i, j;


	for (i = 1; i <= size; i++) {
		a[i][1] = a[1][i] = 1;
	}


	for (i = 2; i <= size; i++) {
		for (j = 2; j <= size - i; j++) {
			if (a[i - 1][j] == 0 || a[i][j - 1] == 0) {
				break;
			}
			a[i][j] = a[i - 1][j] + a[i][j - 1];
		}
	}





	int row,space;
	for (i = 1; i < size; i++) {
		space=row=i;
		j=1;

		while(space<=size+(size-i)+1){
			 cout<<" ";
			 space++;
		 }

		while(j<=i){
			if (a[row][j] == 0){
				   break;
			   }

			if(j==1){
				printf("%d",a[row--][j++]);
			}
			else
				printf("%6d",a[row--][j++]);
		}
			cout<<"\n\n";
	}

}

int main()
{


	int size;
	cin>>size;
	Pascal_Triangle(size);
}

