  {

    getline(cin, input);


    if(input == "\r")
      break;


    story += input;
  }


  int begin;
  while((begin = story.find("<")) != string::npos)
  {

    int end = story.find(">");
    string cat = story.substr(begin + 1, end - begin - 1);


    cout << "Give me a " << cat << ": ";
