", "C#": "using System;

namespace prog
{
	class MainClass
	{
		class MyClass : ICloneable
		{
			public MyClass() { f = new int[3]{2,3,5}; c = '1'; }

			public object Clone()
			{				
				MyClass cpy = (MyClass) this.MemberwiseClone();
