", "Go": "package main

import (
    "fmt"
    "io/ioutil"
    "log"
    "strings"
)

func main() {

    data, err := ioutil.ReadFile("unixdict.txt")
    if err != nil {
        log.Fatal(err)
    }

    words := strings.Split(string(data), "\n")

    data = nil

    m := make(map[string]bool)
    longest := 0
    for _, w := range words {
        m[string(w)] = true
        if len(w) > longest {
            longest = len(w)
        }
    }

    r := make([]byte, longest)

    sem := 0
    var five []string
    for _, w := range words {


        delete(m, w)

        last := len(w) - 1
        for i := 0; i < len(w); i++ {
            r[i] = w[last-i]
        }
        rs := string(r[:len(w)])

        if m[rs] {
            sem++
            if len(five) < 5 {
                five = append(five, w+"/"+rs)
            }
        }
    }

    fmt.Println(sem, "pairs")
    fmt.Println("examples:")
    for _, e := range five {
        fmt.Println("  ", e)
    }
}
"}

