", "Go": "package main

import (
    "bytes"
    "fmt"
    "io/ioutil"
)

func main() {

    b, err := ioutil.ReadFile("unixdict.txt")
    if err != nil {
        fmt.Println(err)
        return
    }

    bss := bytes.Split(b, []byte{'\n'})


    var longest int
    var list [][]byte
    for _, bs := range bss {


        if len(bs) < longest {
            continue
        }

        var lastLetter byte
        for i := 0; ; i++ {
            if i == len(bs) {


                if len(bs) > longest {
                    longest = len(bs)
                    list = list[:0]
                }
                list = append(list, bs)
                break
            }

            b := bs[i]
            if b < 'a' || b > 'z' {
                continue 
            }
            if b < lastLetter {
                break 
            }

            lastLetter = b
        }
    }

