", "Go": "package main

import "fmt"




func ts(n, p int) (R1, R2 int, ok bool) {

    powModP := func(a, e int) int {
        s := 1
        for ; e > 0; e-- {
            s = s * a % p
        }
        return s
    }

    ls := func(a int) int {
        return powModP(a, (p-1)/2)
    }

    if ls(n) != 1 {
        return 0, 0, false
    }


    Q := p - 1
    S := 0
    for Q&1 == 0 {
        S++
        Q >>= 1
    }

    if S == 1 {
        R1 = powModP(n, (p+1)/4)
        return R1, p - R1, true
    }

    z := 2
    for ; ls(z) != p-1; z++ {
    }
    c := powModP(z, Q)

    R := powModP(n, (Q+1)/2)
    t := powModP(n, Q)
    M := S

    for {

        if t == 1 {
            return R, p - R, true
        }

        i := 0
        for z := t; z != 1 && i < M-1; {
            z = z * z % p
            i++
        }

        b := c
        for e := M - i - 1; e > 0; e-- {
            b = b * b % p
        }
        R = R * b % p
        c = b * b % p 
        t = t * c % p
        M = i
    }
}

func main() {
    fmt.Println(ts(10, 13))
    fmt.Println(ts(56, 101))
    fmt.Println(ts(1030, 10009))
    fmt.Println(ts(1032, 10009))
    fmt.Println(ts(44402, 100049))
}
