", "Python": "



def ieTwins(s):

    longWords = [
        w for w in s.splitlines()
        if 5 < len(w)
    ]
    lexicon = {
        w for w in longWords
        if 'i' in w
    }

    return [
        (w, twin) for w in longWords
        if 'e' in w and (
            twin := w.replace('e', 'i')
        ) in lexicon
    ]




def main():

    for pair in ieTwins(
        readFile("unixdict.txt")
    ):
        print(pair)





def readFile(fp):

    with open(fp, 'r', encoding='utf-8') as f:
        return f.read()



if __name__ == '__main__':
    main()
"}

