", "VB": "Function factors(num As UInt64) As UInt64()

  Dim result() As UInt64
  Dim iFactor As UInt64 = 1
  While iFactor <= num/2 
    If num Mod iFactor = 0 Then
      result.Append(iFactor)
    End If
    iFactor = iFactor + 1
  Wend
  result.Append(num) 
  Return result
End Function
"}

