                    A[i + 1] = temp;
                    swapped = true;
                }
            }
            if (!swapped)
            {

                break;
            }
            swapped = false;
            for (int i = A.Length - 2; i >= 0; i--)
            {
                if (A[i] > A[i + 1])
                {
                    int temp = A[i];
                    A[i] = A[i + 1];
                    A[i + 1] = temp;
                    swapped = true;
                }
            }

        } while (swapped);
    }
"}

