from itertools import count



def firstSquareWithPrefix(n):

    pfx = str(n)
    lng = len(pfx)
    return int(
        next(
            s for s in (
                str(x * x) for x in count(0)
            )
            if pfx == s[0:lng]
        )
    )



def main():


    print('\n'.join([
        str(firstSquareWithPrefix(x)) for x in range(1, 50)
    ]))



if __name__ == '__main__':
    main()
